#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/range_control/range_control.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ScrollBar's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/scroll_bar.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The arrow buttons' extent along the axis, 8 to 64 pixels (else std::invalid_argument).
template <typename Declaring>
struct ScrollBarButtonExtentCapability {
    PropertyCell<double, ScrollBarButtonExtentCapability<Declaring>> button_extent{17.0};

    static void assign(ScrollBarButtonExtentCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.button_extent), incoming);
        if (!capability.button_extent.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.button_extent));
    }
};

// The thumb's least extent, 8 to 128 pixels (else std::invalid_argument).
template <typename Declaring>
struct ScrollBarMinimumThumbExtentCapability {
    PropertyCell<double, ScrollBarMinimumThumbExtentCapability<Declaring>> minimum_thumb_extent{18.0};

    static void assign(ScrollBarMinimumThumbExtentCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.minimum_thumb_extent), incoming);
        if (!capability.minimum_thumb_extent.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.minimum_thumb_extent));
    }
};

// How long a held part waits before it repeats, 100ms to 2s (else std::invalid_argument); a press already repeating keeps its schedule.
template <typename Declaring>
struct ScrollBarInitialRepeatDelayCapability {
    PropertyCell<FrameInterval, ScrollBarInitialRepeatDelayCapability<Declaring>> initial_repeat_delay{std::chrono::milliseconds(400)};

    static void assign(ScrollBarInitialRepeatDelayCapability& capability, FrameInterval incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.initial_repeat_delay), incoming);
        if (!capability.initial_repeat_delay.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.initial_repeat_delay));
    }
};

// The interval between a held part's repeats, 16ms to 500ms (else std::invalid_argument).
template <typename Declaring>
struct ScrollBarRepeatIntervalCapability {
    PropertyCell<FrameInterval, ScrollBarRepeatIntervalCapability<Declaring>> repeat_interval{std::chrono::milliseconds(60)};

    static void assign(ScrollBarRepeatIntervalCapability& capability, FrameInterval incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.repeat_interval), incoming);
        if (!capability.repeat_interval.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.repeat_interval));
    }
};

// Every ScrollBar capability, in the order the declaring class takes them.
template <typename Declaring>
struct ScrollBarCapabilities : public ScrollBarButtonExtentCapability<Declaring>,
                               public ScrollBarMinimumThumbExtentCapability<Declaring>,
                               public ScrollBarInitialRepeatDelayCapability<Declaring>,
                               public ScrollBarRepeatIntervalCapability<Declaring> {};

} // namespace gui_forms
